扫描命中行的代码上下文（±25 行窗口，L<n> 为包内原始行号）：
L1: // Reproducible live smoke matrix — one agentflow run per row (cheap-first).
L2: // Usage: node scripts/smoke-harnesses.mjs [--json] [--only name,...] [--script path]
L3: // Rows are cheap-first: stop after the first failure unless you opt out.
L4: import { spawnSync } from 'node:child_process';
L5: import { fileURLToPath } from 'node:url';
L6: import { resolve } from 'node:path';
L7: import { adapters } from '../src/adapters/index.mjs';
L8: import { which } from '../src/adapters/which.mjs';
L9: 
L10: const ROOT = fileURLToPath(new URL('..', import.meta.url));
L11: const BIN = resolve(ROOT, 'bin/agentflow');
L12: const TIMEOUT_MS = 120_000;
L13: const CHEAP_MODEL = 'z-ai/glm-5.3-flash';
L14: 
L15: const ROWS = [
L16:   { name: 'echo', harness: 'echo', spend: 'none' },
L17:   { name: 'devin', harness: 'devin', model: 'swe-2-medium', spend: 'free (swe-2 tier)' },
L18:   { name: 'ori', harness: 'ori', model: CHEAP_MODEL, spend: '~$0.01' },
L19:   { name: 'openrouter', harness: 'openrouter', model: CHEAP_MODEL, spend: '~$0.01' },
L20:   { name: 'claude-via-ori', harness: 'claude', via: 'ori', model: CHEAP_MODEL, spend: '~$0.01' },
L21:   { name: 'codex-via-ori', harness: 'codex', via: 'ori', model: CHEAP_MODEL, spend: '~$0.01' },
L22:   { name: 'opencode-via-ori', harness: 'opencode', via: 'ori', model: CHEAP_MODEL, spend: '~$0.01' },
L23: ];
L24: 
L25: export function parseArgs(argv) {
L26:   const opts = { json: false, only: null, script: resolve(ROOT, 'examples/smoke.mjs') };
L27:   for (let i = 0; i < argv.length; i++) {
L28:     const a = argv[i];
L29:     if (a === '--json') opts.json = true;
L30:     else if (a === '--only' || a === '--script') {
L31:       const v = argv[++i];
L32:       if (v === undefined || v.startsWith('--')) { process.stderr.write(`smoke: ${a} needs a value\n`); process.exit(2); }
L33:       if (a === '--only') opts.only = v.split(','); else opts.script = resolve(v);
L34:     } else if (a.startsWith('--')) { process.stderr.write(`smoke: unknown flag ${a}\n`); process.exit(2); }
L35:   }
L36:   return opts;
L37: }
L38: 
L39: export async function runRow(row, script) {
L40:   const t0 = Date.now();
L41:   // Probe every binary the row needs: the harness's own plus the via wrapper's.
L42:   for (const name of [row.harness, row.via].filter(Boolean)) {
L43:     const bin = adapters[name]?.bin;
L44:     if (bin && !(await which(bin))) return { ...row, ok: false, latencyMs: 0, text: `FAIL (${bin} not on PATH)` };
L45:   }
L46:   const args = [BIN, 'run', script, '--harness', row.harness];
L47:   if (row.via) args.push('--via', row.via);
L48:   if (row.model) args.push('--', row.model);
L49:   const r = spawnSync(process.execPath, args, { encoding: 'utf8', timeout: TIMEOUT_MS, maxBuffer: 16 * 1024 * 1024 });
L50:   const latencyMs = Date.now() - t0;
L51:   if (r.error?.code === 'ETIMEDOUT' || r.signal === 'SIGTERM') return { ...row, ok: false, latencyMs, text: 'FAIL (timeout)' };
L52:   const out = `${r.stdout ?? ''}\n${r.stderr ?? ''}`;
L53:   const pong = /smoke -> .*PONG/m.test(out);
L54:   const tail = out.trim().split('\n').filter(Boolean).pop() ?? '';
L55:   return { ...row, ok: r.status === 0 && pong, latencyMs, text: pong ? 'PONG' : `FAIL (${tail.slice(0, 80)})` };
L56: }
L57: 
L58: if (process.argv[1] === fileURLToPath(import.meta.url)) {
L59:   const opts = parseArgs(process.argv.slice(2));
L60:   const rows = ROWS.filter((r) => !opts.only || opts.only.includes(r.name));
L61:   if (!rows.length) {
L62:     process.stderr.write(`smoke: --only matched no rows (have: ${ROWS.map((r) => r.name).join(', ')})\n`);
L63:     process.exit(2);
L64:   }
L65:   const results = [];
L66:   for (const row of rows) {
L67:     const res = await runRow(row, opts.script);
L68:     results.push(res);
L69:     if (!opts.json) {
L70:       const inv = `agentflow run ${opts.script.split('/').pop()} --harness ${res.harness}${res.via ? ` --via ${res.via}` : ''}`;
L71:       process.stdout.write(`| ${res.name} | \`${inv}\` | ${res.text} | ${(res.latencyMs / 1000).toFixed(1)}s | ${res.spend ?? '—'} |\n`);

