L1: import { spawn } from 'node:child_process';
L2: import { resolve as resolvePath } from 'node:path';
L3: import { which } from './which.mjs';
L4: 
L5: const STDERR_TAIL = 8192;
L6: 
L7: // spawn a CLI, capture stdout/stderr, enforce timeout and abort.
L8: // Never throws: failures return a structured result for the caller to classify.
L9: export function spawnProcess(argv, { cwd, timeout, signal, env, onSpawn } = {}) {
L10:   return new Promise((resolve) => {
L11:     let child;
L12:     try {
L13:       const runCwd = resolvePath(cwd ?? process.cwd());
L14:       const childEnv = { ...(env ?? process.env) };
L15:       // PWD is the shell working-directory variable, not a credential. Drop
L16:       // the parent's stale value so cwd-aware CLIs (e.g. opencode) use the
L17:       // spawn cwd instead of the parent's project.
L18:       delete childEnv.PWD;
L19:       child = spawn(argv[0], argv.slice(1), {
L20:         cwd: runCwd,
L21:         env: childEnv,
L22:         stdio: ['ignore', 'pipe', 'pipe'],
L23:         detached: true,
L24:       });
L25:       child.on('spawn', () => {
L26:         try { process.setpgid(child.pid, child.pid); } catch {}
L27:         // The child is a process-group leader (detached + setpgid) so timeout
L28:         // and abort can kill its whole tree — but that also means the group
L29:         // survives if WE die. Reporting the pgid lets a later --resume reap
L30:         // the stray before re-executing the same unit.
L31:         if (typeof onSpawn === 'function' && child.pid != null) {
L32:           try { onSpawn(child.pid, argv[0]); } catch {}
L33:         }
L34:       });
L35:     } catch (e) {
L36:       return resolve({ spawnError: e.message });
L37:     }
L38:     let stdout = '', stderr = '', timedOut = false, done = false;
L39:     const finish = (r) => { if (!done) { done = true; resolve(r); } };
L40:     const killGroup = (sig) => {
L41:       try { process.kill(-child.pid, sig); } catch { child.kill(sig); }
L42:     };
L43:     const timer = timeout ? setTimeout(() => { timedOut = true; killGroup('SIGTERM'); setTimeout(() => killGroup('SIGKILL'), 2000).unref(); }, timeout) : null;
L44:     const onAbort = () => killGroup('SIGKILL');

